Set-Location C:\Project\Family\FamilySystem
Write-Host "=== restore 80 score living wall ==="
Get-Process Code,msedge,chrome,node -ErrorAction SilentlyContinue | Stop-Process -Force
Start-Sleep 1
takeown /F public\index.html /A 2>$null
icacls public\index.html /grant Administrators:F 2>$null
Remove-Item -Force public\index.html -ErrorAction SilentlyContinue
git checkout -- public\index.html public\mvp-pages.js public\styles\home.css 2>$null
New-Item -ItemType Directory -Force -Path public\styles | Out-Null

$idxB64=""
$cssB64=""
$jsB64=""

[IO.File]::WriteAllBytes("public\index.html", [Convert]::FromBase64String($idxB64))
