[IO.File]::WriteAllBytes("public\mvp-pages.js", [Convert]::FromBase64String($jsB64))

git diff --stat
node --check public/mvp-pages.js
Write-Host "restore done - npm start then http://127.0.0.1:3002/?v=80final"
